<?php
require __DIR__.'/payment-plans.php';
use EducacionalERP\Application\{FinanceService,EnrollmentLifecycle};
use EducacionalERP\Domain\{FinancialStatus,Input,Money};
wp_set_current_user(1);$finance=new FinanceService($db,$ops);$life=new EnrollmentLifecycle($db,$ops);$today=Input::today();$tomorrow=(new DateTimeImmutable($today))->modify('+1 day')->format('Y-m-d');$yesterday=(new DateTimeImmutable($today))->modify('-1 day')->format('Y-m-d');
$base=['status'=>'aberto','saldo_aberto'=>'100.00','vencimento'=>$today];
testP(FinancialStatus::value($base)==='em_aberto','vence hoje e permanece em aberto');testP(FinancialStatus::value(array_replace($base,['vencimento'=>$yesterday]))==='vencido','vencido pela data local');testP(FinancialStatus::value(array_replace($base,['status'=>'parcial','vencimento'=>$tomorrow]))==='em_aberto','baixa parcial mantém saldo em aberto');testP(FinancialStatus::value(array_replace($base,['saldo_aberto'=>'0.00']))==='baixado','saldo liquidado é baixado');testP(FinancialStatus::value(array_replace($base,['status'=>'cancelado','saldo_aberto'=>'0.00']))==='cancelado','cancelado não é confundido com baixado');
$titles=$db->rows('SELECT l.* FROM '.$db->table('lancamentos').' l JOIN '.$db->table('parcelas').' p ON p.idparcela=l.idparcela WHERE p.idcontrato=%d ORDER BY p.numero',[$ct]);$first=$titles[0];$id=(int)$first['idlancamento'];$contractBefore=$db->get('contratos',$ct);$parcelBefore=$db->get('parcelas',(int)$first['idparcela']);
