$partial=$finance->pay($id,['valor_pago'=>'100.00','forma_pagamento'=>'pix'],keyP());$current=$db->get('lancamentos',$id);deniedP(fn()=>$finance->edit($id,['versao'=>$current['versao'],'valor_original'=>'50.00','motivo'=>'Teste'],keyP()),'valor inferior ao principal já pago é bloqueado');
$second=$db->get('lancamentos',(int)$titles[1]['idlancamento']);$before=$db->get('lancamentos',$id);deniedP(fn()=>$finance->editBatch(['lancamentos'=>[['idlancamento'=>$id,'versao'=>$before['versao']],['idlancamento'=>$second['idlancamento'],'versao'=>999]],'alteracoes'=>['valor_original'=>'600.00'],'motivo'=>'Teste lote'],keyP()),'falha de versão em lote aborta operação inteira');testP($db->get('lancamentos',$id)===$before,'primeiro título revertido após falha no segundo');
$finance->editBatch(['lancamentos'=>[['idlancamento'=>$id,'versao'=>$before['versao']],['idlancamento'=>$second['idlancamento'],'versao'=>$second['versao']]],'alteracoes'=>['valor_original'=>'600.00','vencimento'=>$today],'motivo'=>'Renegociação em lote'],keyP());testP($db->get('lancamentos',$id)['saldo_aberto']==='500.00'&&$db->get('lancamentos',(int)$second['idlancamento'])['saldo_aberto']==='600.00','lote aplica valor mantendo pagamento parcial');
// Third installment is overdue; second is fully paid; first has a future partial balance.
$third=(int)$titles[2]['idlancamento'];$db->update('lancamentos',$third,['vencimento'=>$yesterday]);$finance->pay((int)$second['idlancamento'],['valor_pago'=>'600.00','forma_pagamento'=>'pix'],keyP());$thirdBefore=$db->get('lancamentos',$third);$secondBefore=$db->get('lancamentos',(int)$second['idlancamento']);$m=$db->get('matriculas',(int)$initial['idmatricula']);$request=['versao'=>$m['versao'],'solicitante_tipo'=>'outro','solicitante_nome'=>'Solicitante','data_solicitacao'=>$today,'colegio_destino'=>'Escola destino'];$k=keyP();$life->external((int)$m['idmatricula'],$request,$k);$after=$db->get('lancamentos',$id);testP($after['status']==='cancelado'&&$after['valor_cancelado']==='500.00'&&$after['saldo_aberto']==='0.00'&&$after['valor_baixa']==='100.00','transferência cancela saldo não vencido preservando pagamento');testP($db->get('lancamentos',$third)===$thirdBefore,'transferência preserva débito vencido');testP($db->get('lancamentos',(int)$second['idlancamento'])===$secondBefore,'transferência preserva parcela baixada');testP($life->external((int)$m['idmatricula'],$request,$k)['status']==='transferencia_externa','transferência idempotente');deniedP(fn()=>$finance->edit($id,['versao'=>$after['versao'],'valor_original'=>'700.00','motivo'=>'Teste'],keyP()),'título cancelado não pode ser editado');
