wp_set_current_user($staff);deniedP(fn()=>$finance->editBatch(['lancamentos'=>[['idlancamento'=>$third,'versao'=>$thirdBefore['versao']]],'alteracoes'=>['valor_original'=>'700.00'],'motivo'=>'Teste'],keyP()),'Secretaria sem permissão não edita financeiro');
